		this.synchronizeCanonicalViews();
		const revision = session.status().revision;
		const account = this.agentAccountId();
		const audioEvidence = await collectTakeAudioEvidence({
			editor: this.editor,
			elementIds: assembly.elementIds,
			sourceClips: assembly.sourceTracks.main.elements.filter((e) => e.type === "video"),
			signal: signal ?? new AbortController().signal,
			boundedFrames: true,
		});
		signal?.throwIfAborted();
		if (this.canonical !== session || this.agentAccountId() !== account ||
			this.editor.scenes.getActiveSceneOrNull()?.id !== scene.id || session.status().revision !== revision)
			throw new Error("The timeline changed during silence analysis. No cuts applied.");
		this.executeTransaction({ execute: () => {
			session.editTakes({ sceneId: scene.id, expectedRevision: revision,
				change: { type: "cleanSilence", audioEvidence } });
			this.publishCanonical();
		} });
	}
